[assistant] Here's the updated `GreetUserApp` class that allows the user to enter information for up to 5 people and then displays them in order from oldest to youngest:

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

class Person
{
    public string FirstName { get; set; }
    public string LastName { get; set; }
    public int Age { get; set; }

    public override string ToString()
    {
        return $"{FirstName} {LastName} ({Age} years old)";
    }
}

class GreetUserApp
{
    static void Main()
    {
        // Introduce the application
        Console.WriteLine("Welcome to the Greet User App!");
        Console.WriteLine("This application will allow you to enter information for up to 5 people and display them in order from oldest to youngest.\n");

        // Create a list to store the people
        List<Person> people = new List<Person>();

        // Allow the user to enter information for up to 5 people
        for (int i = 1; i <= 5; i++)
        {
            Console.WriteLine($"Person {i}:");

            Person person = new Person();

            // Request user's first name
            Console.Write("  Please enter your first name: ");
            person.FirstName = Console.ReadLine();

            // Request user's last name
            Console.Write("  Please enter your last name: ");
            person.LastName = Console.ReadLine();

            // Request user's age
            Console.Write("  Please enter your age: ");
            if (!int.TryParse(Console.ReadLine(), out int age))
            {
                Console.WriteLine("    Invalid age entered. Please enter a valid age.");
                i--;
                continue;
            }
            person.Age = age;

            // Add the person to the list
            people.Add(person);

            Console.WriteLine();
        }

        // Display the people in order from oldest to youngest
        Console.WriteLine("People in order from oldest to youngest:");
        foreach (Person person in people.OrderByDescending(p => p.Age))
        {
            Console.WriteLine($"- {person}");
        }

        // Wait for user input before closing the console window
        Console.Write("\nPress any key to exit...");
        Console.ReadKey();
    }
}
```

Now, the application allows the user to enter information for up to 5 people, and then displays them in order from oldest to youngest using LINQ's `OrderByDescending` method. The `Person` class also includes a `ToString` method to provide a meaningful string representation of each person.
